class Solution {
    public int[] advantageCount(int[] nums1,int[] nums2){
        Arrays.sort(nums1);
        Integer[] order=new Integer[nums2.length];
        for(int i=0;i<order.length;i++)order[i]=i;
        Arrays.sort(order,Comparator.comparingInt(i->nums2[i]));
        int[] answer=new int[nums1.length];
        int left=0,right=nums1.length-1;
        for(int value:nums1)if(value>nums2[order[left]])answer[order[left++]]=value;
        else answer[order[right--]]=value;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun advantageCount(nums1:IntArray,nums2:IntArray):IntArray{
        nums1.sort();
        val order=nums2.indices.sortedBy{
            nums2[it]
        };
        val answer=IntArray(nums1.size);
        var left=0;
        var right=nums1.lastIndex;
        for(value in nums1)if(value>nums2[order[left]])answer[order[left++]]=value else answer[order[right--]]=value;
        return answer
    }
}

